INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(41078, 'ruRU', 'Испытание боеприпасов', '', ''),
(41090, 'ruRU', 'Владыки холмов', '', ''),
(41091, 'ruRU', 'Владыки холмов', '', ''),
(41093, 'ruRU', 'ОПАСНО: Дургут', '', ''),
(41127, 'ruRU', 'Нашествие Грязнорылов', '', ''),
(41137, 'ruRU', 'Падение короля', 'Установите знамя Яндвика на острове короля морских гигантов, чтобы вызвать его и победить.', 'Остался лишь король морских гигантов.$B$BУстанови наше знамя на его побережье и выманите его из моря. Когда он покажется, используй трезубец, чтобы ранить его.$B$BНа берег вынесло брошенную лодку. Используй её, чтобы быстро добраться до острова короля.$B$BПриготовься, $n. Эта битва не будет лёгкой.'),
(41157, 'ruRU', 'Осквернённые исследования', 'Обследуйте места раскопок в Штормхейме и принесите Бранну $1oa осколков Войны древних.', 'Штормхейм пропитан артефактами Войны древних. Демоническими артефактами, если точнее.$b$bЯ думаю, эти артефакты могут подсказать нам кой-чего об их предводителе, Саргерасе. Я уже нашёл несколько осколков титанского диска, но нужно найти остальные.$b$bМне нужно, чтоб ты покопался по Штормхейму да посмотрел, не найдётся ли ещё осколков, чтоб мы могли собрать диск воедино.'),
(41162, 'ruRU', 'И в огонь Скверны', 'Обследуйте места раскопок в Азсуне и найдите $1oa недостающих частей инфернального устройства, затем принесите их Бранну.', 'Я кой-чего нашёл, $n. Ну, вообще-то, парочку вещей.$b$bСначала я нашёл древний текст, в котором говорится о демоне, что подчинил себе силу титанского диска, который я искал.$b$bПотом я нашёл устройство, которое, похоже, используют, чтобы призвать его! Только вот, судя по всему, в нём не хватает пары деталей.$b$bЯ уверен, что если мы ещё покопаемся в Азсуне, эти недостающие детали обязательно отыщутся.'),
(41169, 'ruRU', 'Тёмное Сердце: Через туман', 'Добудьте последнюю главу «Пурпурных холмов Мак''Ари».', 'Не верится, что после всех твоих поисков до сих пор не хватает главы!$b$bГотов поспорить, эти сатиры прибрали её к рукам и унесли куда-то. Наверное, в какое-то тёмное место, где никто не найдёт.$b$bЯ слыхал слухи про одно место, зовут его Тёмное Сердце, там водятся самые сильные из сатиров.$b$bЕсли спросишь моего мнения, тебе стоит отправиться туда да поискать её.'),
(41178, 'ruRU', 'Взрывные результаты', 'Используйте гоблинскую взрывчатку, чтобы освободить $1oa осколков артефактов из их геологического плена.', 'Возможно, ты слышал, а может, и нет — я работаю с гоблинами над новым способом добычи наших артефактов.$b$bА если ты хоть что-то знаешь о гоблинах, то понимаешь, что речь о взрывчатке.$b$bМы провели лишь пару испытаний здесь, в моём лагере, но я был бы благодарен за твою помощь в испытании этого метода в полевых условиях.$b$bЯ отметил на твоей карте место с особенно сложными раскопками.');
